24	        let text = fs::read_to_string(path)?;
25	        let mut config = Self::default();
26	
27	        for line in text.lines() {
28	            let trimmed = line.trim();
29	            if let Some(value) = trimmed.strip_prefix("editor = ") {
30	                config.editor = parse_literal(value).unwrap_or_else(|| "nvim".to_string());
31	            } else if let Some(value) = trimmed.strip_prefix("conflict = ") {
32	                config.conflict = value.trim() == "true";
33	            }
34	        }
35	
36	        Ok(config)
37	    }
